using System;using System.Collections.Generic;
internal static class UsbExactBlockTransactionTest {
 const string Owner="S-1-5-21-1-2-3-1000",A=@"USB\VID_0001&PID_0002&MI_00\A",B=@"USB\VID_0001&PID_0002&MI_01\B",C=@"USB\VID_0003&PID_0004\C";
 static readonly DateTime Start=new DateTime(2026,10,17,0,0,0,DateTimeKind.Utc);static int cases;
 sealed class Injected:Exception{}
 static void Check(bool ok){if(!ok)throw new Exception("Exact transition regression");}
 static bool Reject(Action action){try{action();return false;}catch(Injected){return true;}catch(InvalidOperationException){return true;}}
 sealed class Model:UsbExactBlockTransaction.IDurableStore,UsbExactBlockTransaction.INativeBackend,UsbExactBlockTransaction.INativeAuthority,UsbExactBlockTransaction.IClock {
  internal UsbExactBlockState.Snapshot Committed,Policy;internal UsbExactBlockState.Transition Pending;internal bool TaskArmed,Quiescent=true,Proof=true,Scope=true,RecoveryOnly,OwnedPartial;internal int Restores,StepCount,FailStep=-1,PartialPrefix=-1;internal bool FailAfter;internal DateTime Now=Start;internal Action<string> After;internal List<string> Names=new List<string>();
  internal Model(UsbExactBlockState.Snapshot initial){Committed=Clone(initial);Policy=Clone(initial);}
  static UsbExactBlockState.Snapshot Clone(UsbExactBlockState.Snapshot value){return value==null?null:UsbExactBlockState.Decode(UsbExactBlockState.Encode(value));}
  static UsbExactBlockState.Transition Clone(UsbExactBlockState.Transition value){return value==null?null:UsbExactBlockState.DecodeTransition(UsbExactBlockState.Encode(value));}
  T Step<T>(string name,Func<T> action){int current=++StepCount;Names.Add(name);if(current==FailStep&&!FailAfter)throw new Injected();T result=action();if(After!=null)After(name);if(current==FailStep&&FailAfter)throw new Injected();return result;}
  void Step(string name,Action action){Step<int>(name,()=>{action();return 0;});}
  void Match(string digest){Check(Pending!=null&&Pending.Request.Digest==digest);}
  public DateTime UtcNow{get{return Now;}}
  public UsbExactBlockState.Snapshot ReadCommitted(){return Step("ReadCommitted",()=>Clone(Committed));}
  public UsbExactBlockState.Transition ReadPending(){return Step("ReadPending",()=>Clone(Pending));}
  public void WritePrepared(UsbExactBlockState.Request request){Step("WritePrepared",()=>{if(Pending!=null||!UsbExactBlockState.Same(Committed,request.Before))throw new InvalidOperationException();Pending=new UsbExactBlockState.Transition(request,UsbExactBlockState.Stage.Prepared);});}
  public void AdvancePending(string digest,UsbExactBlockState.Stage expected,UsbExactBlockState.Stage next){Step("AdvancePending",()=>{Match(digest);if(Pending.Phase!=expected||(int)next!=(int)expected+1||next>UsbExactBlockState.Stage.Committed)throw new InvalidOperationException();Pending=new UsbExactBlockState.Transition(Pending.Request,next);});}
  public void CommitCandidate(string digest,UsbExactBlockState.Snapshot before,UsbExactBlockState.Snapshot after){Step("CommitCandidate",()=>{Match(digest);if(Pending.Phase!=UsbExactBlockState.Stage.PolicyVerified||!UsbExactBlockState.Same(Committed,before)||!UsbExactBlockState.Same(Pending.Request.After,after))throw new InvalidOperationException();Committed=Clone(after);});}
  public UsbExactBlockState.Snapshot ClaimRecovery(string digest){return Step("ClaimRecovery",()=>{Match(digest);Pending=new UsbExactBlockState.Transition(Pending.Request,UsbExactBlockState.Stage.RecoveryClaimed);return Clone(Committed);});}
  public void RetirePending(string digest){Step("RetirePending",()=>{Match(digest);Check(!TaskArmed&&Quiescent);if(Pending.Phase!=UsbExactBlockState.Stage.Committed&&Pending.Phase!=UsbExactBlockState.Stage.RecoveryClaimed)throw new InvalidOperationException();Pending=null;});}
  public void ConsumeOwnerProof(UsbExactBlockState.Request request){Step("ConsumeOwnerProof",()=>{if(RecoveryOnly||!Proof)throw new InvalidOperationException();Proof=false;});}
  public void VerifyFreshExternalScope(UsbExactBlockState.Request request){Step("VerifyFreshExternalScope",()=>{if(RecoveryOnly||!Scope)throw new InvalidOperationException();});}
  public void VerifyPolicy(UsbExactBlockState.Snapshot expected){Step("VerifyPolicy",()=>{if(OwnedPartial||!UsbExactBlockState.Same(Policy,expected))throw new InvalidOperationException();});}
  public void PrepareIndependentRecovery(UsbExactBlockState.Request request){Step("PrepareIndependentRecovery",()=>{Match(request.Digest);TaskArmed=true;});}
  public void VerifyIndependentRecovery(UsbExactBlockState.Request request){Step("VerifyIndependentRecovery",()=>{Match(request.Digest);if(!TaskArmed)throw new InvalidOperationException();});}
  public void ApplyCandidate(UsbExactBlockState.Request request){Step("ApplyCandidate",()=>{Match(request.Digest);if(Pending.Phase!=UsbExactBlockState.Stage.RecoveryArmed||!TaskArmed)throw new InvalidOperationException();Quiescent=false;if(PartialPrefix>=0){OwnedPartial=true;throw new Injected();}Policy=Clone(request.After);});}
  public void StopProducersAndVerifyQuiescent(UsbExactBlockState.Request request){Step("StopProducersAndVerifyQuiescent",()=>{Match(request.Digest);Quiescent=true;});}
  public void RestoreBefore(UsbExactBlockState.Request request){Step("RestoreBefore",()=>{Match(request.Digest);Check(Pending.Phase==UsbExactBlockState.Stage.RecoveryClaimed&&Quiescent);if(!OwnedPartial&&!UsbExactBlockState.Same(Policy,request.Before)&&!UsbExactBlockState.Same(Policy,request.After))throw new InvalidOperationException();Restores++;Policy=Clone(request.Before);OwnedPartial=false;});}
  public void RetireIndependentRecovery(UsbExactBlockState.Request request){Step("RetireIndependentRecovery",()=>{Match(request.Digest);Check(Quiescent);TaskArmed=false;});}
  internal UsbExactBlockTransaction Engine(){return new UsbExactBlockTransaction(this,this,this,this);}
  internal void DisableFault(){FailStep=-1;After=null;RecoveryOnly=true;PartialPrefix=-1;}
 }
 static UsbExactBlockState.Request Request(UsbExactBlockState.Snapshot before,bool allow){string[] targets=allow?new[]{A}:new[]{B};var ids=new HashSet<string>(before==null?new string[0]:before.Blocked,StringComparer.Ordinal);foreach(string id in targets)if(allow)ids.Remove(id);else ids.Add(id);var sorted=new List<string>(ids);var after=new UsbExactBlockState.Snapshot(before==null?1:before.Generation+1,Owner,sorted.ToArray());return new UsbExactBlockState.Request(allow?"allow":"block",before,after,targets,new string('a',32),new string('b',64),Start,Start.AddMinutes(5));}
 static void Stable(Model model,UsbExactBlockState.Snapshot expected){Check(model.Pending==null&&!model.TaskArmed&&model.Quiescent&&!model.OwnedPartial&&UsbExactBlockState.Same(model.Committed,expected)&&UsbExactBlockState.Same(model.Policy,expected));}
 static void ApplyFaults(UsbExactBlockState.Snapshot before,bool allow){var request=Request(before,allow);var baseline=new Model(before);baseline.Engine().Apply(request);Stable(baseline,request.After);int count=baseline.StepCount;for(int point=1;point<=count;point++)foreach(bool after in new[]{false,true}){var model=new Model(before){FailStep=point,FailAfter=after};Check(Reject(()=>model.Engine().Apply(request)));var expected=UsbExactBlockState.Same(model.Committed,request.After)?request.After:before;model.DisableFault();model.Now=Start.AddDays(2);var reboot=model.Engine();reboot.Recover();Stable(model,expected);Check(reboot.CurrentStatus==UsbExactBlockTransaction.Status.PolicyVerified);if(UsbExactBlockState.Same(expected,request.After))Check(model.Restores==0);cases++;}}
 static Model Pending(UsbExactBlockState.Request request,bool committed){var model=new Model(request.Before){Pending=new UsbExactBlockState.Transition(request,committed?UsbExactBlockState.Stage.PolicyVerified:UsbExactBlockState.Stage.Applied),Policy=request.After,TaskArmed=true,Quiescent=false};if(committed)model.Committed=request.After;return model;}
 static void RecoveryFaults(UsbExactBlockState.Request request,bool committed){var baseline=Pending(request,committed);baseline.RecoveryOnly=true;baseline.Engine().Recover();int count=baseline.StepCount;for(int point=1;point<=count;point++)foreach(bool after in new[]{false,true}){var model=Pending(request,committed);model.RecoveryOnly=true;model.FailStep=point;model.FailAfter=after;Check(Reject(()=>model.Engine().Recover()));model.DisableFault();model.Engine().Recover();Stable(model,committed?request.After:request.Before);if(committed)Check(model.Restores==0);cases++;}}
 public static int Main(){var one=new UsbExactBlockState.Snapshot(1,Owner,new[]{A});var two=new UsbExactBlockState.Snapshot(1,Owner,new[]{A,B});ApplyFaults(null,false);ApplyFaults(one,false);ApplyFaults(two,true);var request=Request(one,false);RecoveryFaults(request,false);RecoveryFaults(request,true);
  for(int prefix=0;prefix<6;prefix++){var model=new Model(one){PartialPrefix=prefix};Check(Reject(()=>model.Engine().Apply(request)));model.DisableFault();model.Engine().Recover();Stable(model,one);cases++;}
  var fenced=Pending(request,false);fenced.Pending=new UsbExactBlockState.Transition(request,UsbExactBlockState.Stage.PolicyVerified);fenced.ClaimRecovery(request.Digest);Check(Reject(()=>fenced.CommitCandidate(request.Digest,request.Before,request.After)));Check(Reject(()=>fenced.ApplyCandidate(request)));fenced.DisableFault();fenced.Engine().Recover();Stable(fenced,one);
  var foreign=Pending(request,false);foreign.Committed=new UsbExactBlockState.Snapshot(9,Owner,new[]{C});Check(Reject(()=>foreign.Engine().Recover()));Check(foreign.Pending!=null&&foreign.Restores==0&&foreign.TaskArmed);
  foreign=Pending(request,false);foreign.Policy=new UsbExactBlockState.Snapshot(9,Owner,new[]{C});Check(Reject(()=>foreign.Engine().Recover()));Check(foreign.Pending!=null&&foreign.Restores==0&&foreign.TaskArmed);
  var late=new Model(one);late.After=name=>{if(name=="CommitCandidate")late.Now=Start.AddDays(10);};late.Engine().Apply(request);Stable(late,request.After);late.DisableFault();late.Engine().Recover();Stable(late,request.After);
  var expired=new Model(one);expired.After=name=>{if(name=="ApplyCandidate")expired.Now=Start.AddMinutes(6);};Check(Reject(()=>expired.Engine().Apply(request)));expired.DisableFault();expired.Engine().Recover();Stable(expired,one);
  var backwards=new Model(one);backwards.After=name=>{if(name=="ConsumeOwnerProof")backwards.Now=Start.AddSeconds(-1);};Check(Reject(()=>backwards.Engine().Apply(request)));Check(backwards.Pending==null&&UsbExactBlockState.Same(backwards.Policy,one));
  var denied=new Model(one){Proof=false};Check(Reject(()=>denied.Engine().Apply(request)));Check(denied.Pending==null&&UsbExactBlockState.Same(denied.Policy,one));var scope=new Model(one){Scope=false};Check(Reject(()=>scope.Engine().Apply(request)));Check(scope.Pending==null);
  var replay=new Model(one);replay.Engine().Apply(request);Check(Reject(()=>replay.Engine().Apply(Request(request.After,true))));Stable(replay,request.After);
  var changedScope=new Model(one);changedScope.After=name=>{if(name=="PrepareIndependentRecovery")changedScope.Scope=false;};Check(Reject(()=>changedScope.Engine().Apply(request)));Check(changedScope.Pending!=null);changedScope.DisableFault();changedScope.Engine().Recover();Stable(changedScope,one);
  Console.WriteLine("PASS "+cases+" before/after interface fault and modeled partial-write cases, new-engine recovery, target preservation, commit/rollback fencing, no expiry after commit, clock/proof/scope/drift refusals; pure models only");return 0;}
}
